class Solution {
public:
    vector<string> findWords(vector<string>& words) {
        unordered_set<char> r1{'q','w','e','r','t','y','u','i','o','p'};
        unordered_set<char> r2{'a','s','d','f','g','h','j','k','l'};
        unordered_set<char> r3{'z','x','c','v','b','n','m'};
        vector<string> res;
        for (const string& w : words) {
            bool in1 = true, in2 = true, in3 = true;
            for (char c : w) {
                char lower = tolower(c);
                if (!r1.count(lower)) in1 = false;
                if (!r2.count(lower)) in2 = false;
                if (!r3.count(lower)) in3 = false;
            }
            if (in1 || in2 || in3) res.push_back(w);
        }
        return res;
    }
};

class Solution {
    public String[] findWords(String[] words) {
        String r1 = "qwertyuiop", r2 = "asdfghjkl", r3 = "zxcvbnm";
        List<String> res = new ArrayList<>();
        for (String w : words) {
            boolean in1 = true, in2 = true, in3 = true;
            for (char c : w.toLowerCase().toCharArray()) {
                if (r1.indexOf(c) == -1) in1 = false;
                if (r2.indexOf(c) == -1) in2 = false;
                if (r3.indexOf(c) == -1) in3 = false;
            }
            if (in1 || in2 || in3) res.add(w);
        }
        return res.toArray(new String[0]);
    }
}

